//! M86.4 (docs/DESIGN.md §84.4): the two crude units whose five product lines
//! need their pump, each behind a check valve — `crude_unit_pumps_lifted.toml`
//! (the tanks high: a stopped pump stops its product) and
//! `crude_unit_pumps_grade.toml` (the tanks at grade at the end of long
//! rundowns: a stopped pump cuts its product to under half). Generated by
//! `tools/steptime/prototypes/m86_4/make_pumped.py`.

use crate::product_line_reference::{build, run};
use crate::short_draw_line::{flow, set_pump, shares, tick, worst_imbalance};
use refinery_core::snapshot::Snapshot;
use refinery_core::traits::STOPPED_DRAW_SHARE;
use refinery_core::units::KgPerSec;
use refinery_solvers::elements::check_opening;
use refinery_solvers::network::{march_draw_lines, LineFlash};

const LIFTED: &str = include_str!("../../../scenarios/crude_unit_pumps_lifted.toml");
const GRADE: &str = include_str!("../../../scenarios/crude_unit_pumps_grade.toml");

/// The oil draws, top down, by their line's first pipe's prefix.
const OIL: [&str; 5] = ["naphtha", "kerosene", "diesel", "gas_oil", "residue"];
/// Each draw's share of the oil fed, as the plant file sets it [-].
const SHARE: [f64; 5] = [0.22, 0.16, 0.2, 0.14, 0.28];

pub(crate) fn on_solver(src: &str, solver: &str) -> String {
    let chosen = src.replace("flow = \"newton\"", &format!("flow = \"{solver}\""));
    assert!(
        solver == "newton" || chosen != src,
        "the solver was not swapped"
    );
    chosen
}

fn pressure(s: &Snapshot, name: &str) -> f64 {
    s.nodes
        .iter()
        .find(|n| n.name == name)
        .unwrap_or_else(|| panic!("no node '{name}'"))
        .pressure_pa
}

/// The check valve's lift [-], read off the drive across it and its outlet
/// pipe (M30, docs/DESIGN.md §33) at the plant's 0.015 bar band.
pub(crate) fn lift(s: &Snapshot, product: &str) -> f64 {
    let drive =
        pressure(s, &format!("{product}_check")) - pressure(s, &format!("{product}_cooler"));
    check_opening(drive, 0.015e5)
}

/// The most `product`'s line delivers [share of the oil fed], its pump on or
/// off, marched from the plant's state after 150 ticks: the line's stored
/// flow set far past anything it can carry, so the march's short-line search
/// (§84.2) finds its limit.
fn most(src: &str, product: &str, on: bool) -> f64 {
    let mut engine = build(src).unwrap();
    run(&mut engine, 150);
    let oil = flow(&engine.snapshot(), "transfer_line");
    if !on {
        set_pump(&mut engine, product, false);
    }
    let name = format!("{product}_suction");
    let line: Vec<_> = engine
        .graph
        .draw_lines()
        .into_iter()
        .map(|(_, _, line)| line.to_vec())
        .find(|line| engine.graph.pipe(line[0]).name == name)
        .expect("a product line");
    const FAR: f64 = 2000.0;
    for &edge in &line {
        engine.graph.pipe_mut(edge).stream.mass_flow = KgPerSec(FAR);
    }
    let pins = march_draw_lines(
        &engine.graph,
        &engine.slate,
        engine.node_states(),
        LineFlash::LIQUID,
    )
    .unwrap();
    let delivered = pins
        .draw_delivered
        .get(&line[0])
        .expect("short at 2000 kg/s");
    delivered.value() / oil
}

/// **The margins the plants were sized to** (the M86.4 probe): on the lifted
/// plant a stopped pump's line delivers nothing at all — its tank 25 m above
/// the column's reach — and a running one at least 1.7 times its share; on
/// the grade plant a stopped pump's line still delivers 0.40–0.47 of its
/// share, a running one at least 1.5 times it. So the line below can take a
/// stopped one's product on both.
#[test]
fn the_product_lines_need_their_pumps_by_the_margins_they_were_sized_to() {
    for (index, product) in OIL.iter().enumerate() {
        let share = SHARE[index];
        let lifted_on = most(LIFTED, product, true) / share;
        let lifted_off = most(LIFTED, product, false);
        let grade_on = most(GRADE, product, true) / share;
        let grade_off = most(GRADE, product, false) / share;
        println!(
            "M86_4 {product}: lifted {lifted_on:.3}x running, {lifted_off} stopped; \
             grade {grade_on:.3}x running, {grade_off:.3}x stopped"
        );
        assert!(lifted_on > 1.7, "{product}: lifted running {lifted_on}");
        assert_eq!(
            lifted_off, 0.0,
            "{product}: a lifted line runs without its pump"
        );
        assert!(grade_on > 1.5, "{product}: grade running {grade_on}");
        assert!(
            grade_off > 0.40 && grade_off < 0.47,
            "{product}: grade stopped {grade_off}"
        );
    }
}

/// On the lifted plant each side pump stopped in turn: its product stops —
/// the draw at a stopped draw's share, no pipe of its line running back, its
/// check valve shut — and the draw below takes its whole share, tick after
/// tick, every component's books closing at the column; started, both go
/// back to their own shares.
fn lifted_side_pumps_stop_their_products(solver: &str) {
    let src = on_solver(LIFTED, solver);
    for index in 1..=3 {
        let product = OIL[index];
        let mut engine = build(&src).unwrap();
        let s = tick(&mut engine, 30);
        let before = shares(&engine, &s);
        for (got, want) in before.iter().zip(SHARE) {
            assert!((got - want).abs() < 1e-9, "{solver}: {before:?}");
        }
        assert!(
            lift(&s, product) > 0.999,
            "{solver} {product}: the disc not up"
        );
        set_pump(&mut engine, product, false);
        for t in 0..30 {
            let s = tick(&mut engine, 1);
            let now = shares(&engine, &s);
            assert!(
                now[index] <= STOPPED_DRAW_SHARE * (1.0 + 1e-6),
                "{solver} {product} tick {t}: still runs: {now:?}"
            );
            assert!(
                (now[index + 1] - (SHARE[index + 1] + SHARE[index] - now[index])).abs() < 1e-9,
                "{solver} {product} tick {t}: the draw below did not take it: {now:?}"
            );
            assert!(
                worst_imbalance(&engine, &s) < 1e-9,
                "{solver} {product} tick {t}"
            );
            for pipe in ["suction", "discharge", "check_outlet", "rundown"] {
                let carried = flow(&s, &format!("{product}_{pipe}"));
                assert!(
                    carried >= 0.0,
                    "{solver} {product} tick {t}: the {pipe} runs back: {carried}"
                );
            }
            if t > 0 {
                assert_eq!(lift(&s, product), 0.0, "{solver} {product} tick {t}: open");
            }
        }
        set_pump(&mut engine, product, true);
        let s = tick(&mut engine, 3);
        let after = shares(&engine, &s);
        for (got, want) in after.iter().zip(SHARE) {
            assert!(
                (got - want).abs() < 1e-9,
                "{solver} {product}: not released: {after:?}"
            );
        }
    }
}

#[test]
fn a_stopped_side_pump_on_the_lifted_plant_stops_its_product() {
    lifted_side_pumps_stop_their_products("newton");
}

#[test]
fn a_stopped_side_pump_on_the_lifted_plant_stops_its_product_on_the_game_solver() {
    lifted_side_pumps_stop_their_products("simple");
}

/// On the grade plant each pump above the bottoms stopped in turn — the
/// naphtha too, which here keeps a trickle of distillate and so of reflux:
/// its line still carries 0.40–0.47 of its share, forward through its open
/// check valve, steady from tick to tick, and the rest goes down the column,
/// every component's books closing; started, every draw goes back to its own
/// share.
fn grade_pumps_cut_their_products(solver: &str) {
    let src = on_solver(GRADE, solver);
    for index in 0..=3 {
        let product = OIL[index];
        let mut engine = build(&src).unwrap();
        tick(&mut engine, 30);
        set_pump(&mut engine, product, false);
        let mut last = None;
        for t in 0..30 {
            let s = tick(&mut engine, 1);
            let now = shares(&engine, &s);
            let cut = now[index] / SHARE[index];
            assert!(
                cut > 0.40 && cut < 0.47,
                "{solver} {product} tick {t}: carries {cut} of its share"
            );
            assert!(
                (now.iter().sum::<f64>() - 1.0).abs() < 1e-9,
                "{solver} {product} tick {t}: {now:?}"
            );
            // The rest goes down: every draw above unmoved, every draw below
            // at its share or more. The stopped diesel's rest is more than
            // the gas oil's line can take on top of its own (1.8 times its
            // share against the 1.59 it carries), so the gas oil runs at what
            // its line delivers and the residue takes the rest — from the
            // tick after the stop: on that tick the gas oil's line is still
            // marched at its last flow, which it carries, so the column runs
            // it at the whole rest, 1.79 times its share, once (a line is
            // read a tick late, docs/DESIGN.md §67.13).
            for above in 0..index {
                assert!(
                    (now[above] - SHARE[above]).abs() < 1e-9,
                    "{solver} {product} tick {t}: {now:?}"
                );
            }
            for below in index + 1..OIL.len() {
                assert!(
                    now[below] >= SHARE[below] - 1e-12,
                    "{solver} {product} tick {t}: {now:?}"
                );
            }
            if product == "diesel" && t > 0 {
                let gas_oil = now[3] / SHARE[3];
                assert!(
                    gas_oil > 1.5 && gas_oil < 1.6,
                    "{solver} tick {t}: the gas oil carries {gas_oil} of its share"
                );
                assert!(now[4] > SHARE[4] + 0.03, "{solver} tick {t}: {now:?}");
            }
            // The total closes exactly (the bottoms by subtraction); each
            // component to the cascade's own convergence, 1e-5 kg/s
            // (`cascade::COMPONENT_RESIDUAL_KG_PER_S`) — about 1e-12 of the
            // feed on most ticks, 3.3e-9 on one as the stopped naphtha's
            // reflux falls.
            let feed = flow(&s, "transfer_line");
            let total = feed
                - OIL
                    .iter()
                    .map(|p| flow(&s, &format!("{p}_suction")))
                    .sum::<f64>();
            assert!(
                total.abs() < 1e-12 * feed,
                "{solver} {product} tick {t}: {total}"
            );
            let worst = worst_imbalance(&engine, &s) * feed;
            assert!(worst < 1e-5, "{solver} {product} tick {t}: {worst} kg/s");
            assert!(lift(&s, product) > 0.0, "{solver} {product} tick {t}: shut");
            for pipe in ["discharge", "check_outlet", "rundown"] {
                assert_eq!(
                    flow(&s, &format!("{product}_{pipe}")),
                    flow(&s, &format!("{product}_suction")),
                    "{solver} {product} tick {t}: the {pipe}"
                );
            }
            if t > 5 {
                let prev: f64 = last.unwrap();
                assert!(
                    (now[index] - prev).abs() < 1e-3 * prev,
                    "{solver} {product} tick {t}: {prev} → {}",
                    now[index]
                );
            }
            last = Some(now[index]);
        }
        set_pump(&mut engine, product, true);
        let s = tick(&mut engine, 3);
        let after = shares(&engine, &s);
        for (got, want) in after.iter().zip(SHARE) {
            assert!(
                (got - want).abs() < 1e-9,
                "{solver} {product}: not released: {after:?}"
            );
        }
    }
}

#[test]
fn a_stopped_pump_on_the_grade_plant_cuts_its_product() {
    grade_pumps_cut_their_products("newton");
}

#[test]
fn a_stopped_pump_on_the_grade_plant_cuts_its_product_on_the_game_solver() {
    grade_pumps_cut_their_products("simple");
}

/// What halts, by name (§84.2): on the lifted plant a stopped naphtha pump
/// (no distillate, so no reflux) and a stopped residue pump (no draw below
/// the bottoms); on the grade plant the residue pump, whose trickle is less
/// than the bottoms.
#[test]
fn a_stopped_distillate_or_bottoms_pump_halts_by_name() {
    for (plant, src, product) in [
        ("lifted", LIFTED, "naphtha"),
        ("lifted", LIFTED, "residue"),
        ("grade", GRADE, "residue"),
    ] {
        let mut engine = build(src).unwrap();
        tick(&mut engine, 30);
        set_pump(&mut engine, product, false);
        let err = engine
            .tick()
            .expect_err(&format!("{plant}: a stopped {product} pump must halt"))
            .to_string();
        let pump = format!("'{product}_pump'");
        assert!(err.contains(&pump), "{plant} {product}: {err}");
    }
}
